#!/usr/bin/env bash
# Final metric correction:
#   1) operational-region AUCC (b <= 0.6) + MINIMAX REGRET across settings
#      — the decision-theoretic criterion for committing to one method
#   2) NTC-v2 grid widened to the thetas where its confidence gate actually
#      binds (diagnostic: 0% of items at theta=0.5, 52-100% at theta=0.9)
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing metric correction..."
decode "apply_regret.py" << 'B64EOF'

B64EOF
decode "apply_v2_theta.py" << 'B64EOF'

B64EOF
python apply_regret.py && rm apply_regret.py
python apply_v2_theta.py && rm apply_v2_theta.py
echo ""
echo "Installed. Re-run scripts/ntc_primary_stats.py for the corrected tables."